import Shape from "./Shape";
import ArrowUp from "./ArrowUp";
import { getScaleXBounded } from "../../utils/dimensions";

export default class ArrowStripUp extends Shape {
  constructor(
    x, y
  ) {
    super();
    this.x = x;
    this.y = y - 150;
    this.arrows = Array(3).fill(false);
    this.curArrow = 2
    this.timer = setInterval(() => {
      this.arrows = Array(3).fill(false);
      this.arrows[this.curArrow] = true;
      this.curArrow = this.curArrow === 0 ? 2 : this.curArrow - 1
    }, 250);

    this.alpha = 1;
    this.alphaSpeed = 0;
  }

  fillAll() {
    clearInterval(this.timer);
    this.arrows = Array(3).fill(true);
    this.alphaSpeed = - 0.08;
  }

  update() {
    this.alpha += this.alphaSpeed;

    if(this.alpha <= 0) {
      this.alpha = 0;
      this.alphaSpeed = 0;
    }
  }


  draw() {
    const { ctx, x, y, arrows, alpha } = this;

    ctx.save();
    ctx.translate(x, y);
    ctx.globalAlpha = alpha;
    for(let i = 0; i < 3; i++) {
      ArrowUp(ctx, 0, 50*i, arrows[i], getScaleXBounded());
    }
    ctx.restore();
  }
}
