function getPersonNameFromUrl() {
  if (typeof window === 'undefined') {
    return "";
  }
  
  const hash = window.location.hash;
  const STORAGE_KEY = 'birthdayPersonName';
  
  if (hash && hash.length > 1) {
    const name = decodeURIComponent(hash.substring(1)).trim();
    localStorage.setItem(STORAGE_KEY, name);
    return name;
  }
  
  const storedName = localStorage.getItem(STORAGE_KEY);
  return storedName || "";
}

const personName = getPersonNameFromUrl();

export default {
  "introModal": {
    "welcomeText": "🎉 It's Birthday Celebration Time! 🎉",
    "greetingText": `Wishing you the happiest of birthdays, ${personName}! 🥳✨`,
    "wishesText": "May your special day be filled with laughter, joy, and unforgettable moments. Here's to another amazing year ahead! 🥂"
  },
  "canvas": {
    "birthdayWish": `Happy Birthday, ${personName}! 🎉🎊`
  }
};